import * as React from "react";

export type PianoKeysIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function PianoKeysIcon({ size = 20, ...props }: PianoKeysIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="7" width="16" height="10" rx="1.5" /><path d="M8 7v6M12 7v6M16 7v6M4 12.5h16" />
    </svg>
  );
}
